update public.artwork w
   set original_url = b.url, width = b.width, height = b.height,
       portrait_state = null, portrait_discogs_id = null,
       portrait_changed_at = now()
  from b
 where w.entity_type = 'artist' and w.entity_id = b.id
   and ((w.portrait_state = 'withheld' and w.original_url is null)
     or (w.portrait_state = 'unresolved' and w.original_url = b.url));
commit;
